// 4x4 Bayer行列のディザリングパターン
float getBayerFromCoord(vec2 coord) {
    const int indexMatrix4x4[16] = int[16](
        0,  8,  2,  10,
        12, 4,  14, 6,
        3,  11, 1,  9,
        15, 7,  13, 5
    );

    int x = int(mod(coord.x, 4.0));
    int y = int(mod(coord.y, 4.0));

    return float(indexMatrix4x4[x + y * 4]) / 16.0;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // 画面サイズに基づいて正規化された座標 (0～1)
    vec2 uv = fragCoord / iResolution.xy;

    // 時間による横スライド (x座標をオフセット)
    float slideOffset = iTime * 0.2;
    uv.x += slideOffset;

    // グラデーションのカラーパレット
    vec3 colors[8];
    colors[0] = vec3(0.882, 0.824, 0.694);  // #E1D2B1
    colors[1] = vec3(0.357, 0.502, 0.565);  // #5B8090
    colors[2] = vec3(0.6, 0.627, 0.690);    // #99A0B0
    colors[3] = vec3(0.365, 0.608, 0.576);  // #5D9B93
    colors[4] = vec3(0.204, 0.361, 0.502);  // #345C80
    colors[5] = vec3(0.231, 0.263, 0.545);  // #3B438B
    colors[6] = vec3(0.0, 0.043, 0.247);    // #000B3F
    colors[7] = vec3(0.882, 0.824, 0.694);  // #E1D2B1

    // セグメントとインデックスの計算
    float segment = fract(uv.x * 0.5) * 7.0;
    int idx = int(floor(segment));
    float t = fract(segment);

    // キュービック補間
    t = t * t * (3.0 - 2.0 * t);

    // 色の補間
    vec3 col = mix(colors[idx], colors[(idx + 1) % 8], t);

    // ディザリングの適用
    float dither = getBayerFromCoord(fragCoord);
    float ditherStrength = 1.0; // ディザリングの強度（0.0 - 1.0）

    // ディザリングパターンを色に適用
    col += (dither - 0.5) * ditherStrength;

    // 出力（値の範囲を0-1に制限）
    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
